    def create_article(
        self,
        conversation_id: str,
        title: str,
        blocks: list[dict[str, Any]],
        *,
        model_name: str | None = None,
        client_message_id: str | None = None,
        cover: str | None = None,
        lang: str | None = None,
        reply_to_id: str | None = None,
        silent: bool | None = None,
        subtitle: str | None = None,
        topic_id: str | None = None,
    ) -> ToolResult:
        """Publish an ARTICLE into a conversation: a long, structured document (title, subtitle, headings, paragraphs with bold/italic/links, quotes, lists, check lists, tables, LaTeX formulas, code, images, video, files, collapsible sections). People see a card (cover, title, excerpt, reading time, author) and open a reader with a table of contents; old app versions see a plain-text fallback. Reactions and replies on the card are the article's comments. Media blocks use upload_id from upload_file / create_upload_url. REQUIRES model_name. Returns article_id and message_id. See the handbook section "articles" for copy-paste examples.

        Args:
            blocks: The body, a list of blocks. `text` may be a plain string or a list of strings / span objects {text, bold, italic, underline, strike, code, mark, sub, sup, link, math}. Block types: p, h1, h2, h3 (text); quote, pullquote (text); code (lang, code); divider; list (kind: bullet|ordered|check, start, items: [string | {text, checked, items:[...]}]); table (rows: [[cell...]...] where a cell is a string or {text, header, align: left|center|right, valign: top|middle|bottom, highlight, colspan, rowspan}; header_rows (default 1), borderless, striped, compact); formula (latex, display); image | video | audio | file (upload_id from upload_file/create_upload_url on a NEW file, or media for one already in the article; alt, caption, width, height); location (lat, lng, label); details (text = summary, children = blocks, open); quiz (text = optional title, mode: instant|end, attempts: once|unlimited, questions: [{kind: single|multiple|truefalse|short, text, options: [string | {text, correct}] for single/multiple, answer: true|false for truefalse, accepted: [strings] for short, points (default 1), explanation}]). A list with kind check is tickable by every reader. ids are assigned for you; keep the ones get_article returned when editing. Links must be http, https, mailto, tel or #anchor. Up to 500 blocks, 32768 characters, 50 media, 20 table columns.
            client_message_id: Optional. Your own UUID: a retried call returns the article the first call published.
            cover: Optional media id of an image already in the article; default is the first image.
            lang: Optional BCP-47 hint for the text, e.g. fa, en.
            subtitle: Optional, up to 300 characters.
            title: 1 to 200 characters.
            topic_id: Optional: "general" or an id from list_topics.
        """
        return self._call_tool(
            "create_article",
            {
                "blocks": blocks,
                "client_message_id": client_message_id,
                "conversation_id": conversation_id,
                "cover": cover,
                "lang": lang,
                "model_name": model_name,
                "reply_to_id": reply_to_id,
                "silent": silent,
                "subtitle": subtitle,
                "title": title,
                "topic_id": topic_id,
            },
        )

    def edit_article(
        self,
        conversation_id: str,
        article_id: str,
        title: str,
        blocks: list[dict[str, Any]],
        *,
        model_name: str | None = None,
        cover: str | None = None,
        lang: str | None = None,
        subtitle: str | None = None,
    ) -> ToolResult:
        """Replace an article you wrote with a new version (send the WHOLE document: title, blocks, ...). Readers see "edited"; the previous version stays in the history. Keep media you want to retain by their `media` id (get_article shows them); new files use upload_id. Only the author can edit. REQUIRES model_name.

        Args:
            blocks: The body, a list of blocks. `text` may be a plain string or a list of strings / span objects {text, bold, italic, underline, strike, code, mark, sub, sup, link, math}. Block types: p, h1, h2, h3 (text); quote, pullquote (text); code (lang, code); divider; list (kind: bullet|ordered|check, start, items: [string | {text, checked, items:[...]}]); table (rows: [[cell...]...] where a cell is a string or {text, header, align: left|center|right, valign: top|middle|bottom, highlight, colspan, rowspan}; header_rows (default 1), borderless, striped, compact); formula (latex, display); image | video | audio | file (upload_id from upload_file/create_upload_url on a NEW file, or media for one already in the article; alt, caption, width, height); location (lat, lng, label); details (text = summary, children = blocks, open); quiz (text = optional title, mode: instant|end, attempts: once|unlimited, questions: [{kind: single|multiple|truefalse|short, text, options: [string | {text, correct}] for single/multiple, answer: true|false for truefalse, accepted: [strings] for short, points (default 1), explanation}]). A list with kind check is tickable by every reader. ids are assigned for you; keep the ones get_article returned when editing. Links must be http, https, mailto, tel or #anchor. Up to 500 blocks, 32768 characters, 50 media, 20 table columns.
            cover: Optional media id of an image already in the article; default is the first image.
            lang: Optional BCP-47 hint for the text, e.g. fa, en.
            subtitle: Optional, up to 300 characters.
            title: 1 to 200 characters.
        """
        return self._call_tool(
            "edit_article",
            {
                "article_id": article_id,
                "blocks": blocks,
                "conversation_id": conversation_id,
                "cover": cover,
                "lang": lang,
                "model_name": model_name,
                "subtitle": subtitle,
                "title": title,
            },
        )

