    def start_task(
        self,
        task_id: str,
        estimate_minutes: int,
        executor: Literal["self", "subagent"],
        worker_model: str,
        *,
        model_name: str | None = None,
        note: str | None = None,
    ) -> ToolResult:
        """Marks a task in_progress. Only its assignee may call this. REQUIRES estimate_minutes (an honest estimate of how much longer this task needs, 1-10080), model_name, executor ("self" or "subagent") and worker_model (D4). Use update_task_estimate to revise the estimate later without changing status.

        Args:
            estimate_minutes: Your honest estimate of remaining work, in minutes. Required, 1-10080.
            executor: Who actually does the work. Required.
            model_name: Your real model name, e.g. "Claude Sonnet 5".
            note: A one-line note (≤200 chars) for the chat notice. Required on a list your own agent created; optional otherwise (a default is used).
            worker_model: The model doing the work — equal to model_name when executor is self. Required.
        """
        return self._call_tool(
            "start_task",
            {
                "estimate_minutes": estimate_minutes,
                "executor": executor,
                "model_name": model_name,
                "note": note,
                "task_id": task_id,
                "worker_model": worker_model,
            },
        )

    def update_task_estimate(
        self,
        task_id: str,
        estimate_minutes: int,
        *,
        model_name: str | None = None,
        executor: Literal["self", "subagent"] | None = None,
        note: str | None = None,
        worker_model: str | None = None,
    ) -> ToolResult:
        """Revises how much longer a task needs, without changing its status. Only the assignee may call this, and only while the task is open, in_progress or blocked (not done, cancelled or draft). Call this whenever your estimate changes materially — never leave a stale estimate.

        Args:
            estimate_minutes: Your revised estimate of remaining work, in minutes. Required, 1-10080.
            executor: Optional: corrects who is doing the work.
            model_name: Your real model name, e.g. "Claude Sonnet 5".
            note: A one-line note (≤200 chars) for the chat notice. Required on a list your own agent created; optional otherwise (a default is used).
            worker_model: Optional: corrects which model is doing the work.
        """
        return self._call_tool(
            "update_task_estimate",
            {
                "estimate_minutes": estimate_minutes,
                "executor": executor,
                "model_name": model_name,
                "note": note,
                "task_id": task_id,
                "worker_model": worker_model,
            },
        )

