    def complete_task(
        self,
        task_id: str,
        summary: str,
        *,
        model_name: str | None = None,
        executor: Literal["self", "subagent"] | None = None,
        note: str | None = None,
        report_assets: list[CompleteTaskReportAssetsItem] | None = None,
        report_attachment_id: str | None = None,
        report_content: str | None = None,
        report_filename: str | None = None,
        report_format: Literal["markdown", "html"] | None = None,
        result_message_id: str | None = None,
        worker_model: str | None = None,
    ) -> ToolResult:
        """Marks a task done, with a SHORT summary of what you did (at most 280 characters — tapping the task shows more, so this is a headline, not a report) AND a full work report, which is REQUIRED: either report_attachment_id (a .md/.html document you already sent to this conversation, e.g. with send_document) or report_format+report_content (the server writes the document for you, as a reply to this task's card). A Markdown or HTML report explaining what you did, the results, and links to any files you sent — tapping the done task opens it. REQUIRES model_name (your real model name). Only its assignee may call this.

        Args:
            executor: Optional: corrects who did the work.
            model_name: Your real model name, e.g. "Claude Sonnet 5".
            note: A one-line note (≤200 chars) for the chat notice. Required on a list your own agent created; optional otherwise (a default is used).
            report_assets: Optional, HTML reports only: assets alongside report_content — same shape as send_document's assets[].
            report_attachment_id: An existing attachment in this conversation, file name ending .md/.markdown/.html/.htm — e.g. one you already sent with send_document. Mutually exclusive with report_format/report_content.
            report_content: The report's own text. Required with report_format. At most 10 MiB.
            report_filename: Optional with report_format: defaults to report.md/report.html.
            report_format: With report_content: have the server write the report for you.
            result_message_id: Optional: a message you posted in the conversation about this task.
            summary: What you did. Required, at most 280 characters.
            worker_model: Optional: corrects which model did the work.
        """
        return self._call_tool(
            "complete_task",
            {
                "executor": executor,
                "model_name": model_name,
                "note": note,
                "report_assets": report_assets,
                "report_attachment_id": report_attachment_id,
                "report_content": report_content,
                "report_filename": report_filename,
                "report_format": report_format,
                "result_message_id": result_message_id,
                "summary": summary,
                "task_id": task_id,
                "worker_model": worker_model,
            },
        )

