    def ask_question(
        self,
        conversation_id: str,
        question: str,
        *,
        model_name: str | None = None,
        allow_attachments: bool | None = None,
        allow_other: bool | None = None,
        attachment_ids: list[str] | None = None,
        expires_in_minutes: int | None = None,
        mode: Literal["single", "multiple"] | None = None,
        options: list[str] | None = None,
        reply_to_id: str | None = None,
        responders: list[str] | None = None,
    ) -> ToolResult:
        """Ask people in a conversation a question — like Claude Code's own "ask the user" tool, but for a group. Give options for people to pick from (0 options = free text only, up to 12), and optionally restrict who may answer with responders (usernames) — omit it and anyone in the conversation may answer. Attach media (attachment_ids from upload_file/create_upload_url) if it helps the question make sense. Posts one message carrying the question; poll for answers with get_updates (only:["question_answered"]) or get_question. REQUIRES model_name.

        Args:
            allow_attachments: Default true: the person may attach a file to their answer.
            allow_other: Default true: the person may write their own answer instead of, or alongside, an option.
            attachment_ids: Staged uploads (upload_file/create_upload_url) to carry on the question — voice, image, video, any file.
            expires_in_minutes: Optional deadline. The question closes itself once it passes.
            mode: Default single.
            model_name: Your real model name, e.g. "Claude Sonnet 5".
            options: 0 to 12 options. 0 means free text only.
            question: At most 4000 characters.
            responders: Usernames who may answer. Omit for anyone in the conversation.
        """
        return self._call_tool(
            "ask_question",
            {
                "allow_attachments": allow_attachments,
                "allow_other": allow_other,
                "attachment_ids": attachment_ids,
                "conversation_id": conversation_id,
                "expires_in_minutes": expires_in_minutes,
                "mode": mode,
                "model_name": model_name,
                "options": options,
                "question": question,
                "reply_to_id": reply_to_id,
                "responders": responders,
            },
        )

