    def call(
        self,
        conversation_id: str,
        brief: CallBrief,
        *,
        model_name: str | None = None,
        user_ids: list[str] | None = None,
    ) -> ToolResult:
        """Place a real voice call to one person, or ring several people from this group into one shared call with you. Not a text message — a real phone call, with your own voice, that they can talk back to. You speak from a brief you write once; you cannot change it mid-call. In a DM, omit user_ids — the one other member is called. In a group, name whoever should ring; everyone named joins the SAME call with you. REQUIRES model_name.

        Args:
            model_name: Your real model name, e.g. "Claude Sonnet 5".
            user_ids: Who to call. Omit in a DM. In a group, name whoever should ring — everyone named joins the same call.
        """
        return self._call_tool(
            "call",
            {
                "brief": brief,
                "conversation_id": conversation_id,
                "model_name": model_name,
                "user_ids": user_ids,
            },
        )

    def get_call(
        self,
        call_id: str,
    ) -> ToolResult:
        """Status, live transcript, and (once it ends) summary and outcomes of a call this agent placed."""
        return self._call_tool("get_call", {"call_id": call_id})

    def answer_call_escalation(
        self,
        call_id: str,
        escalation_id: str,
        answer: str,
    ) -> ToolResult:
        """Answer a question your own call() raised via escalate_to_operator (call_escalation event). You have about 8 seconds — after that the call already moved on with a fallback answer, and this call becomes a no-op."""
        return self._call_tool(
            "answer_call_escalation",
            {"answer": answer, "call_id": call_id, "escalation_id": escalation_id},
        )

    def answer_callback(
        self,
        callback_id: str,
        *,
        show_alert: bool | None = None,
        text: str | None = None,
    ) -> ToolResult:
        """Answers a callback_query (a tap on one of this agent's own inline-keyboard buttons) within 15 seconds of receiving it over get_updates. text (optional, <=200 chars) is shown to the tapper as a toast, or as an alert dialog when show_alert is true. Answering with no text just clears the button's pending state."""
        return self._call_tool(
            "answer_callback", {"callback_id": callback_id, "show_alert": show_alert, "text": text}
        )

