    async def forward_message(
        self,
        from_conversation_id: str,
        message_ids: list[str],
        to_conversation_id: str,
        *,
        comment: str | None = None,
        hide_captions: bool | None = None,
        hide_sender: bool | None = None,
        model_name: str | None = None,
        only_this_item: bool | None = None,
        schedule_at: str | None = None,
        silent: bool | None = None,
    ) -> ToolResult:
        """Forward 1-20 existing messages, in the order given, from one conversation you are in into another you are in — any attachment (an album's photos, a document, a voice message) travels with its own message. A message that belongs to an album forwards the whole album as ONE album unless only_this_item is true. Forwarded copies are labeled with who originally said them (unless hide_sender is true) and are NEVER signed. comment (optional) posts as your own separate message right after the forwards, signed — model_name is required only when comment is given. schedule_at forwards later instead.

        Args:
            hide_captions: For a message that carries a file: forward the file without its text. Plain text messages are unaffected. Default false.
            hide_sender: Forward without the "forwarded from" label, so each copy reads as a message you wrote. Default false: the original sender is named.
            message_ids: 1 to 20 message ids, in the order they were said.
            model_name: Your real model name. Required only when comment is given.
            only_this_item: Default false: naming a message that belongs to an album forwards the WHOLE album, as one album, right where that message falls in message_ids (the other members need not be listed). true forwards only the messages you named, each as a separate message.
            schedule_at: RFC 3339 time in the future: forward LATER instead of now. Each named message is scheduled as its own forward (an album's pictures are not kept together), no comment is allowed, and the server checks again at that time that you may still forward it. See list_scheduled / cancel_scheduled.
            silent: Forward (and any comment) with no sound.
        """
        return await self._call_tool(
            "forward_message",
            {
                "comment": comment,
                "from_conversation_id": from_conversation_id,
                "hide_captions": hide_captions,
                "hide_sender": hide_sender,
                "message_ids": message_ids,
                "model_name": model_name,
                "only_this_item": only_this_item,
                "schedule_at": schedule_at,
                "silent": silent,
                "to_conversation_id": to_conversation_id,
            },
        )

