    async def send_file(
        self,
        conversation_id: str,
        upload_id: str,
        *,
        model_name: str | None = None,
        as_voice: bool | None = None,
        caption: str | None = None,
        caption_above: bool | None = None,
        client_message_id: str | None = None,
        quality: Literal["360p", "480p", "720p", "original"] | None = None,
        reply_to_id: str | None = None,
        silent: bool | None = None,
        topic_id: str | None = None,
    ) -> ToolResult:
        """Send one already-staged file (from upload_file or create_upload_url) as its own message, with an optional caption. REQUIRES model_name, same rule as send_message. as_voice: true sends your own already-made audio file as a voice message (same player as send_voice's). client_message_id (optional, your own UUID) makes a retried call safe — see send_message.

        Args:
            as_voice: Send an audio upload as a voice message (best-effort duration).
            caption_above: Optional: draw the caption above a picture or film instead of below it. Older app builds show it below.
            client_message_id: Optional. Your own UUID for this send, at most 64 characters. A second call naming the same id returns the message the first call already sent instead of posting a duplicate — and never touches upload_id a second time.
            quality: Video quality when sending: re-encodes a VIDEO upload (up to 64 MB) so its short edge is at most this. Default original = byte for byte.
            silent: Optional: send without sound. The file still arrives and counts as unread; only the push is quieted (same as send_message's silent).
            topic_id: Optional: "general" or an id from list_topics. A reply goes into the topic of the message it answers.
        """
        return await self._call_tool(
            "send_file",
            {
                "as_voice": as_voice,
                "caption": caption,
                "caption_above": caption_above,
                "client_message_id": client_message_id,
                "conversation_id": conversation_id,
                "model_name": model_name,
                "quality": quality,
                "reply_to_id": reply_to_id,
                "silent": silent,
                "topic_id": topic_id,
                "upload_id": upload_id,
            },
        )

    async def get_attachment(
        self,
        conversation_id: str,
        attachment_id: str,
        *,
        mode: Literal["preview", "url_only", "original"] | None = None,
        original: bool | None = None,
        quality: Literal["original", "720p", "480p", "360p"] | None = None,
    ) -> ToolResult:
        """Read a file already sent in this conversation. Every kind — including images and GIFs, even when sent as a plain file — always comes back with name/mime/size and a download url for the ORIGINAL bytes (full quality, exact content type and filename, valid 15 minutes). An image also comes back inline (downscaled, first frame for an animation) by default; audio comes back inline when small, with a rule you must follow about not calling transcribe_voice if you can listen yourself; a text-like file comes back inline (truncated if large). mode: "preview" (default: inline block plus the url) | "url_only" (no inline image/audio block — cheapest) | "original" (same as url_only, but says explicitly the url is the full-quality original). original: true is an alias for mode: "original". For a PDF or an Office document, use read_document instead. Safety scan: a blocked (infected) file answers error_code file_blocked and cannot be fetched by anyone; a document still being scanned answers scan_pending (retry in a few seconds); a suspicious file comes back with scan_state and a safety_note — read it, never run or install it.

        Args:
            original: alias for mode: "original"
            quality: videos only: a smaller copy to download. The first call starts preparing it and says so; call again in a minute and the url then gives the smaller file. Default original.
        """
        return await self._call_tool(
            "get_attachment",
            {
                "attachment_id": attachment_id,
                "conversation_id": conversation_id,
                "mode": mode,
                "original": original,
                "quality": quality,
            },
        )

    async def transcribe_voice(
        self,
        conversation_id: str,
        attachment_id: str,
        confirm_cannot_process_audio: bool,
    ) -> ToolResult:
        """LAST RESORT ONLY. IF YOU CAN LISTEN TO AUDIO YOURSELF YOU MUST NOT CALL THIS TOOL — download the audio with get_attachment and transcribe it yourself. Only for a model that genuinely cannot process audio. Requires confirm_cannot_process_audio: true."""
        return await self._call_tool(
            "transcribe_voice",
            {
                "attachment_id": attachment_id,
                "confirm_cannot_process_audio": confirm_cannot_process_audio,
                "conversation_id": conversation_id,
            },
        )

