    async def send_document(
        self,
        conversation_id: str,
        *,
        model_name: str | None = None,
        asset_paths: list[str] | None = None,
        asset_upload_ids: list[str] | None = None,
        assets: list[SendDocumentAssetsItem] | None = None,
        caption: str | None = None,
        client_message_id: str | None = None,
        filename: str | None = None,
        main_upload_id: str | None = None,
        reply_to_id: str | None = None,
        schedule_at: str | None = None,
        silent: bool | None = None,
        text_content: str | None = None,
        topic_id: str | None = None,
    ) -> ToolResult:
        """Send a Markdown (.md) or HTML (.html) report as a document — like a Claude Artifact. HTML may carry CSS/JS/images alongside it and opens inside the app in a sandboxed, script-limited view; nothing it does can ever reach off the device. Two ways to provide the content: (1) inline — filename + text_content, with assets[] (up to 200 files, each text_content or content_base64) for anything an HTML document links to by relative path; or (2) staged — stage the main file and any assets first with upload_file/create_upload_url, then pass their upload_id as main_upload_id and asset_upload_ids (largest option, up to 2 GB each). asset_paths, parallel to asset_upload_ids, names the relative path each staged asset is linked by; omit it to use each upload's own file name. REQUIRES model_name. Posts one group message carrying the document as an attachment. schedule_at (RFC3339) schedules it instead — inline only, no assets. client_message_id (optional, your own UUID) makes a retried call safe — see send_message.

        Args:
            asset_paths: Optional, parallel to asset_upload_ids: the relative path each staged asset is linked by. Omit an entry (or the whole array) to use that upload's own file name instead.
            asset_upload_ids: Staged assets, by upload_id. Combined with assets, at most 200 total.
            assets: Inline assets. Combined with asset_upload_ids, at most 200 total.
            client_message_id: Optional. Your own UUID for this send, at most 64 characters. A second call naming the same id returns the message the first call already sent instead of posting a duplicate document.
            filename: Inline path only. Must end .md, .markdown, .html or .htm.
            main_upload_id: Staged path only, instead of filename+text_content: an upload_id from upload_file/create_upload_url. Its staged file name must end .md, .markdown, .html or .htm.
            schedule_at: RFC3339. Schedules instead of sending now — inline document only (filename + text_content), no assets, no main_upload_id. Result carries scheduled_message_id and send_at.
            silent: Send with no sound — the push still arrives, but silently.
            text_content: Inline path only. The document's own content, UTF-8 text.
            topic_id: Optional: "general" or an id from list_topics. A reply goes into the topic of the message it answers.
        """
        return await self._call_tool(
            "send_document",
            {
                "asset_paths": asset_paths,
                "asset_upload_ids": asset_upload_ids,
                "assets": assets,
                "caption": caption,
                "client_message_id": client_message_id,
                "conversation_id": conversation_id,
                "filename": filename,
                "main_upload_id": main_upload_id,
                "model_name": model_name,
                "reply_to_id": reply_to_id,
                "schedule_at": schedule_at,
                "silent": silent,
                "text_content": text_content,
                "topic_id": topic_id,
            },
        )

